from oauth2_provider.models import AccessToken
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status

class RevokeAuthorizedTokenView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        token_id = request.data.get('token_id')
        if not token_id:
            return Response({'error': 'token_id is required'}, status=status.HTTP_400_BAD_REQUEST)

        deleted_count, _ = AccessToken.objects.filter(id=token_id, user=request.user).delete()
        if not deleted_count:
            return Response({'error': 'Token not found or unauthorized'}, status=status.HTTP_404_NOT_FOUND)

        return Response({'status': 'revoked', 'token_id': token_id})
